//! Tests for the committed Round 15 example goldens.
//!
//! The golden spread readings of the standing example
//! meet and of the constructed meet are regenerated by
//! the spread command itself, and these pins fail if an
//! example, a golden, or the reading drifts away from
//! the hand computed spreads of either meet, counted by
//! hand from the shipped meet file through the walk and
//! cross checked against the shipped standings golden
//! at the three day closes and the shipped margins
//! golden at all sixteen marks. The day close pin reads
//! the standings reading over the same file and fails
//! when the spread reading's last mark of a day
//! disagrees with the figures that day's standings
//! section computes at its close. Every pin in this
//! file fails before the round by the absence of the
//! reading and its goldens, neither standing on the pre
//! round tree.

use std::fs;
use std::path::PathBuf;

use paceghost::meet::{load_meet_file, meet_spread, meet_standings, Meet};

fn examples_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("examples")
}

fn golden_lines(name: &str) -> Vec<String> {
    let golden = fs::read_to_string(examples_dir().join(name)).expect("the golden file reads");
    assert!(golden.ends_with('\n'));
    golden.lines().map(str::to_string).collect()
}

fn load_example(file: &str) -> Meet {
    let (meet, defects) = load_meet_file(&examples_dir().join(file));
    assert_eq!(defects, Vec::<String>::new());
    meet.expect("the example meet loads")
}

fn mark_lines(lines: &[String]) -> Vec<&String> {
    lines
        .iter()
        .filter(|line| line.starts_with("mark "))
        .collect()
}

fn field_of(mark_line: &str) -> usize {
    let rest = mark_line
        .split(", field of ")
        .nth(1)
        .expect("a mark line names its field");
    rest.split(|c: char| !c.is_ascii_digit())
        .next()
        .and_then(|word| word.parse().ok())
        .expect("a field count stands in the mark line")
}

#[test]
fn test_the_shipped_spread_golden_stands_byte_for_byte() {
    let meet = load_example("meet.json");
    let lines = meet_spread(&meet).expect("the example spread read");
    assert_eq!(lines, golden_lines("meet-spread-golden.txt"));
}

#[test]
fn test_the_constructed_spread_golden_stands_byte_for_byte() {
    let meet = load_example("constructed-meet.json");
    let lines = meet_spread(&meet).expect("the constructed spread read");
    assert_eq!(lines, golden_lines("constructed-meet-spread-golden.txt"));
}

#[test]
fn test_the_shipped_golden_counts_close_as_counted_by_hand() {
    let golden = golden_lines("meet-spread-golden.txt");
    assert_eq!(
        golden.last().map(String::as_str),
        Some("spread counts, marks walked 16, marks with another standing 15, days 3, fullest field 3 at 600 seconds on the first day")
    );
    let marks = mark_lines(&golden);
    assert_eq!(marks.len(), 16);
    let with_another = marks
        .iter()
        .filter(|line| line.contains(", farthest standing "))
        .count();
    assert_eq!(with_another, 15);
    let no_other = marks
        .iter()
        .filter(|line| line.ends_with(", and no other standing"))
        .count();
    assert_eq!(no_other, 1);
    assert_eq!(with_another + no_other, marks.len());
}

#[test]
fn test_the_constructed_golden_counts_close_as_counted_by_hand() {
    let golden = golden_lines("constructed-meet-spread-golden.txt");
    assert_eq!(
        golden.last().map(String::as_str),
        Some("spread counts, marks walked 7, marks with another standing 7, days 3, fullest field 2 at 100 seconds on the first day")
    );
    let marks = mark_lines(&golden);
    assert_eq!(marks.len(), 7);
    let with_another = marks
        .iter()
        .filter(|line| line.contains(", farthest standing "))
        .count();
    assert_eq!(with_another, 7);
}

#[test]
fn test_the_shipped_goldens_fullest_field_names_the_third_mark() {
    let golden = golden_lines("meet-spread-golden.txt");
    let marks = mark_lines(&golden);
    let third = marks[2];
    assert!(
        third.starts_with("mark 3, at 600 seconds on the first day,"),
        "{}",
        third
    );
    assert!(third.contains(", field of 3,"), "{}", third);
    for earlier in &marks[..2] {
        assert!(!earlier.contains(", field of 3"), "{}", earlier);
    }
    let fullest = marks.iter().map(|line| field_of(line)).max();
    assert_eq!(fullest, Some(3));
}

#[test]
fn test_the_day_close_relation_holds_over_the_shipped_example() {
    let meet = load_example("meet.json");
    let spread = meet_spread(&meet).expect("the spread read");
    let standings = meet_standings(&meet).expect("the standings read");
    let mut sections: Vec<Vec<String>> = Vec::new();
    for line in &standings {
        if line.starts_with("day, the ") {
            sections.push(Vec::new());
        }
        if let Some(section) = sections.last_mut() {
            section.push(line.clone());
        }
    }
    let mut spread_sections: Vec<Vec<&String>> = Vec::new();
    for line in &spread {
        if line.starts_with("day, the ") {
            spread_sections.push(Vec::new());
        }
        if let Some(section) = spread_sections.last_mut() {
            section.push(line);
        }
    }
    assert_eq!(sections.len(), 3);
    assert_eq!(spread_sections.len(), 3);
    for (section, spread_section) in sections.iter().zip(spread_sections.iter()) {
        let closing = section
            .iter()
            .find(|line| line.starts_with("close of the "))
            .expect("a standings section closes");
        let holder = closing
            .split("record held by ")
            .nth(1)
            .and_then(|rest| rest.split(" at a projection of ").next())
            .expect("a closing line names its holder");
        let record: f64 = closing
            .rsplit("at a projection of ")
            .next()
            .and_then(|word| word.parse().ok())
            .expect("a closing line names its record figure");
        let mut farthest: Option<(&str, f64)> = None;
        let mut standing_count = 0usize;
        for line in section
            .iter()
            .filter(|line| line.starts_with("competitor "))
        {
            let Some((label, figure)) = line
                .strip_prefix("competitor ")
                .and_then(|rest| rest.split_once(", standing projection "))
                .and_then(|(label, rest)| {
                    rest.strip_suffix(" at the close")
                        .map(|figure| (label, figure))
                })
            else {
                continue;
            };
            standing_count += 1;
            if label == holder {
                continue;
            }
            let value: f64 = figure.parse().expect("a standing figure parses");
            if farthest.is_none_or(|(_, best)| value > best) {
                farthest = Some((label, value));
            }
        }
        let (label, value) = farthest.expect("another competitor stands at the close");
        let last = spread_section
            .iter()
            .rfind(|line| line.starts_with("mark "))
            .expect("the day holds a mark");
        assert_eq!(field_of(last), standing_count, "{}", last);
        assert!(
            last.contains(&format!(
                ", farthest standing {} held by {}, spread ",
                value, label
            )),
            "{}",
            last
        );
        let spread_value: f64 = last
            .rsplit(", spread ")
            .next()
            .and_then(|word| word.parse().ok())
            .expect("the last mark names its spread");
        assert!(
            (spread_value - (value - record)).abs() < 0.000002,
            "{}",
            last
        );
    }
}
